"""Offline regressions for the organization module workflow/ruleset guard."""
import copy
import importlib.util
import pathlib
import unittest

spec = importlib.util.spec_from_file_location("drift", pathlib.Path(__file__).with_name("check-module-drift.py"))
drift = importlib.util.module_from_spec(spec)
spec.loader.exec_module(drift)


class ContractTests(unittest.TestCase):
    def setUp(self):
        self.ci = {"on": {"push": {}, "pull_request": {}}, "jobs": {"module-ci": {"uses": drift.PREFIX + "module-ci.yml@" + "a" * 40}}}
        self.release = {"jobs": {"module-release": {"uses": drift.PREFIX + "module-release.yml@" + "a" * 40, "with": {"include-distros": True}}}}
        self.ruleset = {
            "target": "branch", "enforcement": "active",
            "conditions": {"ref_name": {"include": ["refs/heads/main"], "exclude": []}},
            "bypass_actors": [{"actor_type": "RepositoryRole", "actor_id": 5, "bypass_mode": "always"}],
            "rules": [{"type": "deletion"}, {"type": "non_fast_forward"},
                      {"type": "pull_request", "parameters": {"required_review_thread_resolution": True}},
                      {"type": "required_status_checks", "parameters": {
                          "strict_required_status_checks_policy": True,
                          "required_status_checks": [{"context": x, "integration_id": 15368} for x in drift.CHECKS]}}]}

    def validate(self):
        return drift.validate("tinyjuice", self.ci, self.release, [self.ruleset])

    def test_current_contract_passes(self):
        self.assertEqual(self.validate(), [])

    def test_unpinned_or_wrong_workflow_fails(self):
        for suffix in ("module-ci.yml@main", "other.yml@" + "a" * 40):
            self.ci["jobs"]["module-ci"]["uses"] = drift.PREFIX + suffix
            self.assertTrue(self.validate())

    def test_skippable_shared_jobs_fail(self):
        self.ci["jobs"]["module-ci"]["if"] = False
        self.assertTrue(self.validate())
        self.setUp()
        self.release["jobs"]["module-release"]["if"] = False
        self.assertTrue(self.validate())

    def test_list_trigger_form_passes_and_single_event_fails(self):
        self.ci["on"] = ["push", "pull_request"]
        self.assertEqual(self.validate(), [])
        self.ci["on"] = "push"
        self.assertTrue(self.validate())
        self.ci["on"] = None
        self.assertTrue(self.validate())

    def test_audit_checkout_does_not_persist_credentials(self):
        path = pathlib.Path(__file__).parents[1] / ".github/workflows/ci.yml"
        workflow = drift.yaml.safe_load(path.read_text())
        checkout = workflow["jobs"]["module-drift"]["steps"][0]
        self.assertIs(checkout.get("with", {}).get("persist-credentials"), False)

    def test_missing_pr_trigger_fails(self):
        del self.ci["on"]["pull_request"]
        self.assertTrue(self.validate())

    def test_renamed_ci_job_fails(self):
        self.ci["jobs"]["renamed"] = self.ci["jobs"].pop("module-ci")
        self.assertTrue(self.validate())

    def test_duplicate_or_local_ci_job_fails(self):
        self.ci["jobs"]["test"] = {"runs-on": "ubuntu-latest", "steps": []}
        self.assertTrue(self.validate())

    def test_disabled_distro_builds_fail(self):
        self.release["jobs"]["module-release"]["with"]["include-distros"] = False
        self.assertTrue(self.validate())

    def test_missing_or_wrong_app_check_fails(self):
        checks = self.ruleset["rules"][-1]["parameters"]["required_status_checks"]
        checks.pop()
        self.assertTrue(self.validate())
        checks.append({"context": drift.CHECKS[-1], "integration_id": 1})
        self.assertTrue(self.validate())

    def test_non_strict_or_inactive_ruleset_fails(self):
        self.ruleset["enforcement"] = "evaluate"
        self.assertTrue(self.validate())
        self.ruleset["enforcement"] = "active"
        self.ruleset["rules"][-1]["parameters"]["strict_required_status_checks_policy"] = False
        self.assertTrue(self.validate())

    def test_main_excluded_fails(self):
        self.ruleset["conditions"]["ref_name"]["exclude"] = ["refs/heads/main"]
        self.assertTrue(self.validate())

    def test_missing_pr_or_admin_bypass_fails(self):
        self.ruleset["rules"] = [x for x in self.ruleset["rules"] if x["type"] != "pull_request"]
        self.assertTrue(self.validate())
        self.setUp()
        self.ruleset["bypass_actors"] = []
        self.assertTrue(self.validate())

    def test_public_ruleset_metadata_checks_visible_contract(self):
        del self.ruleset["bypass_actors"]
        self.assertEqual(self.validate(), [])
        self.ruleset["rules"][-1]["parameters"]["required_status_checks"].pop()
        self.assertTrue(self.validate())

    def test_documented_supplemental_jobs_pass(self):
        self.ci["jobs"]["wallet-dependency-boundaries"] = {"steps": []}
        self.assertEqual(drift.validate("tinywallet", self.ci, self.release, [self.ruleset]), [])
        self.assertTrue(self.validate())
        self.setUp()
        for repo, job in (("tinydocs", "source-packages"), ("tinycomputer", "verify-published")):
            release = copy.deepcopy(self.release)
            release["jobs"][job] = {"steps": []}
            self.assertEqual(drift.validate(repo, self.ci, release, [self.ruleset]), [])

    def test_sdk_exception_is_explicit(self):
        self.release = {"jobs": {"sdk-release": {"uses": drift.PREFIX + "sdk-release.yml@" + "a" * 40}}}
        self.assertEqual(drift.validate("tinybus", self.ci, self.release, [self.ruleset]), [])
        self.assertTrue(self.validate())

    def test_additional_active_rulesets_require_admin_bypass(self):
        other = copy.deepcopy(self.ruleset)
        other["bypass_actors"] = []
        self.assertTrue(drift.validate("tinyjuice", self.ci, self.release, [self.ruleset, other]))


if __name__ == "__main__":
    unittest.main()

"""Merge flat source packages while preserving verified module artifacts."""
from pathlib import Path
import shutil
import sys

def merge(source, destination):
    """Validate every source entry before copying any files."""
    source, destination = Path(source), Path(destination)
    files = list(source.iterdir())
    if not files:
        raise ValueError("source artifact is empty")
    for entry in files:
        if entry.is_symlink() or not entry.is_file():
            raise ValueError("source artifacts must contain only top-level regular files")
        if (destination / entry.name).exists():
            raise ValueError("source artifact collides with module asset: " + entry.name)
    for entry in files:
        shutil.copyfile(entry, destination / entry.name)

if __name__ == "__main__":
    merge(*sys.argv[1:])

"""Check public upstream module callers and main protections; never mutate GitHub."""
import base64
import json
import os
import re
import sys
import urllib.request

import yaml

REPOS = ("tinybus", "tinybox", "tinychannels", "tinycomputer", "tinyconnectors",
         "tinydocs", "tinyhosts", "tinyjuice", "tinymcp", "tinyruntime",
         "tinysearch", "tinyvoice", "tinywallet")
PREFIX = "tinyhumansai/.github/.github/workflows/"
CHECKS = tuple("module-ci / " + name for name in (
    "fmt", "clippy", "test", "coverage", "docs", "msrv", "supply-chain",
    *(f"{suite} ({runner}-latest)" for suite in ("module-e2e", "feature-tests")
      for runner in ("ubuntu", "macos", "windows"))))


def pinned(job, workflow):
    """Require a canonical reusable workflow pinned to a full commit SHA."""
    return bool(re.fullmatch(re.escape(PREFIX + workflow + "@") + r"[0-9a-f]{40}",
                             job.get("uses", "")))


def applies_to_main(ruleset):
    refs = ruleset.get("conditions", {}).get("ref_name", {})
    includes = refs.get("include", [])
    excludes = refs.get("exclude", [])
    return (any(x in includes for x in ("refs/heads/main", "~DEFAULT_BRANCH", "~ALL"))
            and not excludes)


def admin_bypass(ruleset):
    return any(x.get("actor_type") == "RepositoryRole" and x.get("actor_id") == 5
               and x.get("bypass_mode") == "always"
               for x in ruleset.get("bypass_actors", []))


def validate(repo, ci, release, rulesets):
    """Return all contract violations from already decoded API documents."""
    errors = []
    # PyYAML's YAML 1.1 loader decodes the unquoted Actions "on" key as True.
    events = ci.get("on", ci.get(True, {}))
    names = {events} if isinstance(events, str) else set(events or ())
    if not {"push", "pull_request"} <= names:
        errors.append("CI must run on pushes and pull requests")
    jobs = ci.get("jobs", {})
    allowed_ci = {"module-ci", *({"wallet-dependency-boundaries"} if repo == "tinywallet" else set())}
    if "if" in jobs.get("module-ci", {}) or set(jobs) - allowed_ci or not pinned(jobs.get("module-ci", {}), "module-ci.yml"):
        errors.append("CI must call the pinned canonical workflow with only documented supplemental jobs")
    release_name = "sdk-release" if repo == "tinybus" else "module-release"
    release_jobs = release.get("jobs", {})
    job = release_jobs.get(release_name, {})
    allowed_release = {"resolve", release_name}
    allowed_release.update({"tinycomputer": {"verify-published"}, "tinydocs": {"source-packages"}}.get(repo, set()))
    if "if" in job or set(release_jobs) - allowed_release or not pinned(job, release_name + ".yml"):
        errors.append("release must call the pinned canonical " + release_name)
    if repo != "tinybus" and job.get("with", {}).get("include-distros", True) is not True:
        errors.append("release must enable all 17 native and distro targets")
    active = [x for x in rulesets if x.get("enforcement") == "active" and x.get("target") == "branch"]
    if any("bypass_actors" in x and not admin_bypass(x) for x in active):
        errors.append("every active branch ruleset must allow administrator bypass always")
    protected = False
    for ruleset in active:
        if not applies_to_main(ruleset):
            continue
        rules = {x["type"]: x.get("parameters", {}) for x in ruleset.get("rules", [])}
        status = rules.get("required_status_checks", {})
        checks = {x.get("context") for x in status.get("required_status_checks", [])
                  if x.get("integration_id") == 15368}
        if (set(CHECKS) <= checks and status.get("strict_required_status_checks_policy") is True
                and {"pull_request", "deletion", "non_fast_forward"} <= rules.keys()
                and rules["pull_request"].get("required_review_thread_resolution") is True):
            protected = True
    if not protected:
        errors.append("main lacks an active strict PR ruleset with all 13 GitHub Actions checks")
    return errors


def api(path):
    """Read GitHub metadata with an optional token; errors fail the audit."""
    headers = {"Accept": "application/vnd.github+json", "User-Agent": "module-drift-check",
               "X-GitHub-Api-Version": "2022-11-28"}
    token = [REDACTED]"GH_TOKEN") or os.environ.get("GITHUB_TOKEN")
    if token:
        headers["Authorization"] = "Bearer " + token
    request = urllib.request.Request("https://api.github.com/repos/tinyhumansai/" + path, headers=headers)
    with urllib.request.urlopen(request, timeout=30) as response:
        return json.load(response)


def workflow(repo, name):
    result = api(repo + "/contents/.github/workflows/" + name + ".yml?ref=main")
    return yaml.safe_load(base64.b64decode(result["content"]))


def main():
    failed = False
    for repo in REPOS:
        try:
            ci, release = workflow(repo, "ci"), workflow(repo, "release")
            listed = api(repo + "/rulesets?includes_parents=true&per_page=100")
            if len(listed) == 100:
                raise ValueError("ruleset listing may be truncated")
            rulesets = [api(repo + "/rulesets/" + str(x["id"])) for x in listed]
            errors = validate(repo, ci, release, rulesets)
            if any("bypass_actors" not in x for x in rulesets if x.get("enforcement") == "active"):
                print(repo + ": bypass actors hidden by GitHub; administrator credentials required to audit bypass")
        except Exception as error:
            # Do not print request headers or tokens.
            errors = ["GitHub metadata audit failed: " + type(error).__name__]
        if errors:
            failed = True
            for error in errors:
                print(repo + ": " + error, file=sys.stderr)
        else:
            print(repo + ": shared callers and main rulesets pass")
    return int(failed)


if __name__ == "__main__":
    sys.exit(main())
